//! Tests of the roster events (GitHub #1019, phase 2): changes of role and
//! scope, novice marks and promotions after admission, and the maintainer
//! handover. Every key is generated by `keystore::generate` (real argon2id +
//! AES-256-GCM + ed25519), every event signed over the real
//! [`roster_event_bytes`], every registry judged by [`Registry::build`].
//!
//! Methodology, for every test: build a registry in memory (the founder
//! `k1`, Alice a reviewer scoped to `crates/tampines/**` admitted by the
//! founder on 2026-10-07, plus whoever the test adds), append roster events,
//! and check the replayed standing (`role_at`, `scope_at`, `novice_at`), the
//! stamps' [`verify_review`] verdicts and the [`Warning`]s against what the
//! rule in the registry's module doc predicts.

use super::keystore::UnlockedKey;
use super::registry::{retire_key, Admission, RosterProblem, SignerProblem, Warning};
use super::tests::{founder_and_alice, key, person, root, signed, unverified, ALICE, F, FOUNDER};
use super::*;
use crate::review::root::{ReviewRoot, RosterEvent, RosterEventKind, Role};

const D1: &str = "2026-10-10";
const D2: &str = "2026-10-20";
const D3: &str = "2026-10-25";
const NJOY: &str = "crates/njoy/src/broadr.rs::broadn";

/// A roster event about `reviewer`, signed by `k` (`None`: unsigned).
fn ev(k: Option<&UnlockedKey>, reviewer: &str, kind: RosterEventKind, date: &str, role: Option<Role>, scope: &[&str]) -> RosterEvent {
    let mut e = RosterEvent {
        reviewer: reviewer.into(),
        event: kind,
        date: date.into(),
        role,
        scope: scope.iter().map(|s| s.to_string()).collect(),
        signer: None,
        signature: None,
    };
    if let Some(k) = k {
        k.sign_roster_event(&mut e).unwrap();
    }
    e
}

fn with_events(mut rt: ReviewRoot, events: Vec<RosterEvent>) -> ReviewRoot {
    rt.code_review.as_mut().unwrap().roster_events = events;
    rt
}

fn roster_problems(reg: &Registry) -> Vec<RosterProblem> {
    reg.warnings()
        .into_iter()
        .filter_map(|w| match w {
            Warning::RosterEvent { problem, .. } => Some(problem),
            _ => None,
        })
        .collect()
}

/// Pass: Alice's scope moves from tampines to njoy on D2 and she becomes a
/// maintainer on D3, each from its own date on; her stamps are judged by
/// the scope and role of their own date (a D1 tampines stamp still
/// verifies after the scope moved; a D1 njoy stamp is outside scope, a D2
/// one verifies; a tampines stamp the day after D2 is outside, while one
/// dated D2 itself still counts, because events carry no time and a change
/// never voids a same-day stamp; a D3 one verifies as a maintainer). No
/// warnings; the admission is untouched.
///
/// Result (2026-10-22): passes.
#[test]
fn scope_and_role_change_from_their_date_and_old_stamps_keep_their_verdict() {
    let (founder, f, alice, a) = founder_and_alice();
    let events = vec![
        ev(Some(&f), ALICE, RosterEventKind::Scope, D2, None, &["crates/njoy/**"]),
        ev(Some(&f), ALICE, RosterEventKind::Role, D3, Some(Role::Maintainer), &[]),
    ];
    let rt = with_events(root(vec![founder, alice.clone()]), events);
    let reg = Registry::build(&rt);
    assert!(reg.warnings().is_empty(), "{:?}", reg.warnings());
    let t = reg.reviewer(ALICE).unwrap();
    assert_eq!(t.admission, Admission::Admitted { by: FOUNDER.into(), key: "k1".into() });
    assert_eq!((t.role, t.scope.as_slice()), (Role::Reviewer, alice.scope.as_slice()), "the admission stays as signed");
    assert_eq!(t.scope_at(D1), ["crates/tampines/**"]);
    assert_eq!(t.scope_at(D2), ["crates/njoy/**"]);
    assert_eq!((t.role_at(D2), t.role_at(D3), t.current_role()), (Role::Reviewer, Role::Maintainer, Role::Maintainer));
    assert_eq!(t.current_scope(), ["crates/njoy/**"]);
    assert!(verify_review(&signed(&a, F, D1), &reg).is_verified(), "an old stamp keeps its verdict");
    assert!(matches!(unverified(verify_review(&signed(&a, NJOY, D1), &reg)), UnverifiedReason::OutsideScope { .. }));
    assert!(verify_review(&signed(&a, NJOY, D2), &reg).is_verified());
    assert!(verify_review(&signed(&a, F, D2), &reg).is_verified(), "same day: the more permissive standing");
    assert!(matches!(unverified(verify_review(&signed(&a, F, "2026-10-21"), &reg)), UnverifiedReason::OutsideScope { .. }));
    assert!(t.may_stamp(D2, "crates/tampines/src/steam.rs") && !t.may_stamp("2026-10-21", "crates/tampines/src/steam.rs"));
    assert!(!t.maintainer_on(D2) && t.maintainer_on(D3));
    assert!(verify_review(&signed(&a, F, D3), &reg).is_verified(), "a maintainer stamps anywhere");
}

/// Pass: a novice mark everywhere from D1, then a promotion on
/// tampines only on D2: novice everywhere on D1; trusted on tampines and
/// still novice on njoy from D2; `novice_now` reports both; a maintainer
/// (Alice from D3) is never a novice; an unscoped promotion ends the mark.
///
/// Result (2026-10-22): passes.
#[test]
fn novice_marks_and_promotions_are_scoped_and_dated() {
    let (founder, f, alice, _) = founder_and_alice();
    let tamp = "crates/tampines/src/steam.rs";
    let njoy = "crates/njoy/src/broadr.rs";
    let mut events = vec![
        ev(Some(&f), ALICE, RosterEventKind::Novice, D1, None, &[]),
        ev(Some(&f), ALICE, RosterEventKind::Trusted, D2, None, &["crates/tampines/**"]),
    ];
    let reg = Registry::build(&with_events(root(vec![founder.clone(), alice.clone()]), events.clone()));
    let t = reg.reviewer(ALICE).unwrap();
    assert!(!t.novice_at("2026-10-09", tamp), "trusted until marked");
    assert!(t.novice_at(D1, tamp) && t.novice_at(D1, njoy));
    assert!(!t.novice_at(D2, tamp) && t.novice_at(D2, njoy));
    assert_eq!(t.novice_now(), Some((vec![], vec!["crates/tampines/**".to_string()])));
    events.push(ev(Some(&f), ALICE, RosterEventKind::Role, D3, Some(Role::Maintainer), &[]));
    let reg = Registry::build(&with_events(root(vec![founder.clone(), alice.clone()]), events.clone()));
    let t = reg.reviewer(ALICE).unwrap();
    assert!(t.novice_at(D2, njoy) && !t.novice_at(D3, njoy), "a maintainer is never a novice");
    assert_eq!(t.novice_now(), None);
    events.pop();
    events.push(ev(Some(&f), ALICE, RosterEventKind::Trusted, D3, None, &[]));
    let reg = Registry::build(&with_events(root(vec![founder, alice]), events));
    let t = reg.reviewer(ALICE).unwrap();
    assert!(!t.novice_at(D3, njoy));
    assert_eq!(t.novice_now(), None);
}

/// Pass: each of these has no effect on Alice's standing and is listed as
/// a warning with its reason: an unsigned event; a forged one (scope
/// widened after signing); one signed by Alice (not a maintainer); one by
/// the founder's key after it was retired; one by a second maintainer after
/// their revocation; one dated before the event before it; one about an
/// unknown reviewer; a role event without a role. A forged promotion of a
/// novice is rejected the same way, so the novice mark stands.
///
/// Result (2026-10-22): passes.
#[test]
fn forged_unsigned_and_ineligible_roster_events_have_no_effect() {
    let (founder, f, alice, a) = founder_and_alice();
    let (mk, m) = key("github:m2", "m1");
    let mut m2 = person("github:m2", Role::Maintainer, vec![mk]);
    m2.admitted = Some("2026-10-07".into());
    f.admit(&mut m2).unwrap();
    let mut rev = Revocation { date: D1.into(), compromised_from: None, by: FOUNDER.into(), signature: None };
    f.revoke("github:m2", &mut rev).unwrap();
    m2.revoked = Some(rev);
    let mut forged = ev(Some(&f), ALICE, RosterEventKind::Scope, D2, None, &["crates/njoy/**"]);
    forged.scope = vec!["**".into()];
    let mut no_role = ev(None, ALICE, RosterEventKind::Role, D2, None, &[]);
    no_role.role = None;
    let events = vec![
        ev(None, ALICE, RosterEventKind::Scope, D2, None, &["**"]),
        forged,
        ev(Some(&a), ALICE, RosterEventKind::Scope, D2, None, &["**"]),
        ev(Some(&m), ALICE, RosterEventKind::Scope, D2, None, &["**"]),
        ev(Some(&f), ALICE, RosterEventKind::Scope, D1, None, &["**"]),
        ev(Some(&f), "github:nobody", RosterEventKind::Scope, D2, None, &["**"]),
        no_role,
    ];
    let reg = Registry::build(&with_events(root(vec![founder.clone(), alice.clone(), m2.clone()]), events));
    let t = reg.reviewer(ALICE).unwrap();
    assert!(t.changes.is_empty(), "{:?}", t.changes);
    assert_eq!(t.current_scope(), ["crates/tampines/**"]);
    let p = roster_problems(&reg);
    assert_eq!(
        p,
        vec![
            RosterProblem::Signer(SignerProblem::Unsigned),
            RosterProblem::Signer(SignerProblem::BadSignature),
            RosterProblem::Signer(SignerProblem::NotEligible(ALICE.into())),
            RosterProblem::Signer(SignerProblem::SignerRevoked { signer: "github:m2".into(), date: D1.into() }),
            RosterProblem::OutOfOrder,
            RosterProblem::UnknownReviewer,
            RosterProblem::MissingRole,
        ]
    );
    // A retired signing key signs nothing.
    let mut retired = founder.clone();
    retire_key(&mut retired.keys[0], D1).unwrap();
    let reg = Registry::build(&with_events(
        root(vec![retired, alice.clone()]),
        vec![ev(Some(&f), ALICE, RosterEventKind::Scope, D2, None, &["**"])],
    ));
    assert_eq!(
        roster_problems(&reg),
        vec![RosterProblem::Signer(SignerProblem::SignerRetired { signer: FOUNDER.into(), key: "k1".into() })]
    );
    // A forged promotion: the novice mark stands.
    let mut promo = ev(Some(&f), ALICE, RosterEventKind::Trusted, D2, None, &["crates/tampines/**"]);
    promo.scope = vec![];
    let reg = Registry::build(&with_events(
        root(vec![founder, alice]),
        vec![ev(Some(&f), ALICE, RosterEventKind::Novice, D1, None, &[]), promo],
    ));
    assert!(reg.reviewer(ALICE).unwrap().novice_at(D3, "crates/tampines/src/steam.rs"));
    assert_eq!(roster_problems(&reg), vec![RosterProblem::Signer(SignerProblem::BadSignature)]);
}

/// The continuity test (#1019, "maintainers can change"). The founder
/// marks Alice novice on D1 and, on D2, hands maintainer to Bob (admitted
/// as a reviewer on D1) and steps down, in that order. Pass: the founder's
/// D1 and D2 stamps still verify (past reviews keep their standing; the
/// same day is never voided) and a D3 stamp of theirs is outside scope; Bob stamps anywhere from D2 and admits
/// Carol on D2; the founder can no longer sign a roster event (D3: not
/// eligible) and Bob can; Alice's novice mark, set by the former
/// maintainer, still stands; no warning but the founder's refused event.
///
/// Result (2026-10-22): passes.
#[test]
fn handover_keeps_old_stamps_passes_authority_and_keeps_marks() {
    let (founder, f, alice, _) = founder_and_alice();
    let (bk, b) = key("github:bob", "b1");
    let mut bob = person("github:bob", Role::Reviewer, vec![bk]);
    bob.scope = vec!["crates/bob/**".into()];
    bob.admitted = Some(D1.into());
    f.admit(&mut bob).unwrap();
    let (ck, _) = key("github:carol", "c1");
    let mut carol = person("github:carol", Role::Reviewer, vec![ck]);
    carol.scope = vec!["crates/carol/**".into()];
    carol.admitted = Some(D2.into());
    b.admit(&mut carol).unwrap();
    let events = vec![
        ev(Some(&f), ALICE, RosterEventKind::Novice, D1, None, &[]),
        ev(Some(&f), "github:bob", RosterEventKind::Role, D2, Some(Role::Maintainer), &[]),
        ev(Some(&f), FOUNDER, RosterEventKind::Role, D2, Some(Role::Reviewer), &[]),
        ev(Some(&f), "github:carol", RosterEventKind::Scope, D3, None, &["**"]),
        ev(Some(&b), "github:carol", RosterEventKind::Scope, D3, None, &["crates/**"]),
    ];
    let reg = Registry::build(&with_events(root(vec![founder, alice, bob, carol]), events));
    let ft = reg.reviewer(FOUNDER).unwrap();
    assert_eq!((ft.role_at(D1), ft.role_at(D2)), (Role::Maintainer, Role::Reviewer));
    assert!(verify_review(&signed(&f, F, D1), &reg).is_verified(), "A's past stamps keep their standing");
    assert!(verify_review(&signed(&f, F, D2), &reg).is_verified());
    assert!(matches!(unverified(verify_review(&signed(&f, F, D3), &reg)), UnverifiedReason::OutsideScope { .. }));
    assert!(verify_review(&signed(&b, F, D2), &reg).is_verified(), "B is a maintainer from D2");
    assert_eq!(reg.reviewer("github:carol").unwrap().admission, Admission::Admitted { by: "github:bob".into(), key: "b1".into() });
    assert_eq!(reg.reviewer("github:carol").unwrap().current_scope(), ["crates/**"]);
    assert_eq!(roster_problems(&reg), vec![RosterProblem::Signer(SignerProblem::NotEligible(FOUNDER.into()))]);
    assert!(reg.reviewer(ALICE).unwrap().novice_at(D3, "crates/tampines/src/steam.rs"), "trust marks carry over");
    assert!(reg.reviewer("github:carol").unwrap().changes.iter().all(|c| c.by == "github:bob"));
}

/// Pass: the signed bytes of a roster event carry their own header and
/// every field (a change to any field, or the signer, changes them), and
/// `sign_roster_event` refuses a bad date and a role event with no role.
///
/// Result (2026-10-22): passes.
#[test]
fn roster_event_bytes_cover_every_field() {
    let (_, f) = key(FOUNDER, "k1");
    let e = ev(Some(&f), ALICE, RosterEventKind::Scope, D2, None, &["a/**", "b/**"]);
    let text = String::from_utf8(roster_event_bytes(&e)).unwrap();
    assert!(text.starts_with("kovan-roster-event-v1\n"), "{text}");
    for part in ["reviewer=\"alice@example.org\"", "event=\"scope\"", "date=\"2026-10-20\"", "role=\"\"", "scope=\"a/**\"", "scope=\"b/**\"", "signer=\"github:founder\" \"k1\""] {
        assert!(text.contains(part), "{part} in {text}");
    }
    let mut changed = e.clone();
    changed.event = RosterEventKind::Novice;
    assert_ne!(roster_event_bytes(&changed), roster_event_bytes(&e));
    let mut bad = e.clone();
    bad.date = "soon".into();
    assert!(f.sign_roster_event(&mut bad).is_err());
    let mut role = ev(None, ALICE, RosterEventKind::Role, D2, None, &[]);
    assert!(f.sign_roster_event(&mut role).is_err());
}
